body.script:
(function(){
var L=JSON.parse(document.getElementById('czd').getAttribute('data-lines')||'[]');
var anyFrozen=L.some(function(x){return x.has_frozen;});var mode=anyFrozen?'frozen':'fresh';
var bad=L.filter(function(x){return !x.ok;});
function esc(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML;}
function draw(){
 var h='';L.forEach(function(x){
  var t=!x.ok?'Etiket ömrü tanımlı değil — ürün kartında "Etiket: taze ömür" doldurun.':(mode==='frozen'&&x.has_frozen?x.frozen_txt:x.fresh_txt);
  h+='<div class="l'+(x.ok?'':' bad')+'"><b>['+esc(x.code)+'] '+esc(x.name)+'</b>Üretim: '+esc(x.produced)+' · Parti: '+esc(x.ref)+'<div class="d">'+esc(t)+'</div></div>';
 });
 document.getElementById('czl').innerHTML=h;
 [].forEach.call(document.querySelectorAll('#czm button'),function(b){b.className=b.getAttribute('data-m')===mode?'on':'';});
}
if(anyFrozen){var m=document.getElementById('czm');m.style.display='flex';
 m.addEventListener('click',function(e){var b=e.target.closest('button');if(b){mode=b.getAttribute('data-m');draw();}});}
if(bad.length||!L.length){document.getElementById('czp').disabled=true;document.getElementById('czn').textContent='Ömrü tanımsız ürün var: etiket basılmaz.';}
var mm=(location.hash||'').match(/n=(\d+)/);if(mm){document.getElementById('czq').value=mm[1];}
draw();
function b64(s){var b=new TextEncoder().encode(s),x='';for(var i=0;i<b.length;i++)x+=String.fromCharCode(b[i]);return btoa(x);}
document.getElementById('czp').addEventListener('click',function(){
 if(this.disabled)return;
 var n=Math.max(1,Math.min(99,parseInt(document.getElementById('czq').value,10)||1));var all='';
 L.forEach(function(x){var z=(mode==='frozen'&&x.has_frozen)?x.frozen_zpl:x.fresh_zpl;
  for(var k=1;k<=n;k++){all+=z.split('#K#').join(k+'/'+n)+'\n';}});
 window.location.href='intent:base64,'+b64(all)+'#Intent;scheme=rawbt;package=ru.a402d.rawbtprinter;end;';
});
})();
